userDefinedLinkHintCss:
/* Hint Marker Style */
div > .vimiumHintMarker {
  background: rgba(0, 0, 0, 0.7) !important;
  backdrop-filter: blur(2px) !important;
  border: 1px solid #55ead4 !important;
  box-shadow: 0 0 8px #55ead4 !important; /* glow effect */
  border-radius: 2px !important;
  padding: 2px 5px !important;
}

/* Hint Marker Text Style */
div > .vimiumHintMarker span {
  color: #55ead4 !important;
  font-family: "Rajdhani", sans-serif !important;
  font-weight: normal !important;
  font-size: 16px !important;
  text-shadow: 0 0 3px #55ead4 !important;
}

/* Hint Marker Inputed Text Style */
div > .vimiumHintMarker > .matchingCharacter {
  color: #f3e600 !important;
  text-shadow: 0 0 3px #f3e600 !important; /* glow effect */
}

/* Vomnibar */
#vomnibar {
  top: 15% !important;
  background-color: rgba(0, 0, 0, 0.8) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px);
  border: 2px solid #55ead4 !important;
  border-radius: 2px !important;
  box-shadow: 0 0 15px rgba(85, 234, 212, 0.5) !important;
  /*animation: none !important;*/
}
#vomnibar-search-area {
  border-bottom: none;
}

/* Vomnibar Input Box */
#vomnibar input {
  color: #55ead4 !important;
  font-family: "Rajdhani", sans-serif !important;
  font-weight: medium !important;
  font-size: 20px !important;
  text-shadow: 0 0 2px #55ead4 !important;

  background-color: transparent !important;
  border: none !important;
  border-bottom: 1px solid rgba(85, 234, 212, 0.3) !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 10px !important;
}

/* Vomnibar Candidate List */
#vomnibar ul li {
  color: #55ead4 !important;
  border-bottom: 1px solid rgba(85, 234, 212, 0.1) !important;
  padding: 8px 10px !important;
}

#vomnibar .source {
  font-family: "Rajdhani", sans-serif !important;
}

#vomnibar .title {
  color: #55ead4 !important;
  font-family: "Rajdhani", sans-serif !important;
  font-weight: medium !important;
  font-size: 16px !important;
  margin-right: 10px !important;
}

#vomnibar .url {
  color: rgba(85, 234, 212, 0.6) !important; /* dim cyan */
  font-family: "Rajdhani", sans-serif !important;
}

#vomnibar .match {
  color: #f3e600 !important;
  font-weight: normal !important;
  text-shadow: 0 0 2px #f3e600 !important;
}

#vomnibar ul li.selected {
  background-color: rgba(85, 234, 212, 0.15) !important; /* dim cyan */
  border-left: 4px solid #55ead4 !important;  /* Accent Bar on the left */
}
